Definition ehdr (L : alayout) (e : achunk * Z) : word := Z_to_bv 64 (qhdr L (fst e) (snd e)).

Lemma qhdrs_rev_combine : forall L chs ks, length ks = length chs ->
  map (Z_to_bv 64) (qhdrs L chs ks) = map (ehdr L) (rev (combine chs ks)).
