Lemma AQdr_popr : forall R L st X m b q T,
  AQdr R 0 0 L st X m -> qr_tmp R = (b, q) :: T -> qr_pendb R = [] -> qr_pend R = [] ->
     AQdr (qr_popr R b q T) 0 0 L st X m
  /\ abatch_cells L m b q (qfirst L (map snd T))
