  /\ (snd iv <= al_dtls L \/ al_dtls L + 4096 <= fst iv)
  /\ (snd iv <= 0xb3ee0 \/ 0xb3ee0 + 8 <= fst iv) /\ (snd iv <= 0x5ed288 \/ 0x5ed288 + 16 <= fst iv)
  /\ (snd iv <= 0x5ed298 \/ 0x5ed298 + 8 <= fst iv) /\ (snd iv <= 0x5ed2b8 \/ 0x5ed2b8 + 8 <= fst iv)
